"use client"

/**
 * Agent UI — explicit business action wrapper.
 *
 * Generic buttons do not automatically become callable agent actions (spec
 * section 6: business semantics are never inferred from presentation).
 * `AgentAction` registers a capability of kind `"action"` that the WebMCP
 * adapter exposes as a dedicated tool. It is a semantics wrapper, not a UI
 * element — it renders its children unchanged.
 */

import * as React from "react"
import type { CapabilityState } from "./capability"
import { useCapability, type ActionMap } from "./use-capability"
import { expectBoolean, rejectState } from "./validate"

/**
 * The WebMCP tool for a business action is named `action_<id>`. Chrome caps a
 * tool name at 30 characters, so the id is capped at 23 and restricted to the
 * WebMCP name charset. Truncating silently could collide with another action
 * and make its registration fail, so an invalid id is refused instead.
 */
const ACTION_ID = /^[A-Za-z0-9_.-]{1,23}$/

export interface AgentActionProps {
  id: string
  description: string
  execute: (input: Record<string, unknown>) => unknown | Promise<unknown>
  /** JSON Schema `properties` for the action's own arguments. */
  inputSchema?: Record<string, unknown>
  /**
   * Consequential actions opt into confirmation. The agent must then pass
   * `confirmed: true`; anything else is rejected with this message.
   */
  confirm?: string
  children?: React.ReactNode
}

interface ActionState extends CapabilityState {
  description: string
  inputSchema?: Record<string, unknown>
  requiresConfirmation: boolean
  lastResult: unknown
}

type ActionActions = { run: Record<string, unknown> }

export function AgentAction(props: AgentActionProps): React.ReactNode {
  const { id, description, execute, inputSchema, confirm, children } = props

  if (!ACTION_ID.test(id)) {
    throw new Error(
      `Agent UI: AgentAction id "${id}" is invalid. Use 1-23 characters from A-Z, a-z, 0-9, "_", "-" or ".".`,
    )
  }

  // Held in a ref and surfaced only through `read()`, so React state remains
  // canonical and the registry never stores a second copy.
  const lastResultRef = React.useRef<unknown>(undefined)

  const read = React.useCallback((): ActionState => {
    return {
      description,
      inputSchema,
      requiresConfirmation: confirm !== undefined,
      lastResult: lastResultRef.current,
    }
  }, [description, inputSchema, confirm])

  const actions = React.useMemo<ActionMap<ActionActions>>(
    () => ({
      async run(input: Record<string, unknown>): Promise<unknown> {
        let payload: Record<string, unknown> = input
        if (confirm !== undefined) {
          const confirmed = expectBoolean(input, "confirmed")
          if (!confirmed) {
            rejectState(confirm)
          }
          payload = { ...input }
          delete payload.confirmed
        }
        const result = await execute(payload)
        lastResultRef.current = result
        return result
      },
    }),
    [execute, confirm],
  )

  useCapability<ActionState, ActionActions>({
    agent: { id, label: id },
    kind: "action",
    read,
    actions,
  })

  return children
}

"use client"

/**
 * Agent UI — provider that connects the capability registry to WebMCP.
 *
 * Runs `connectWebMCP(getCapabilityRegistry())` in a `useEffect` when enabled,
 * tears down on unmount. Renders children unchanged. No context, no state —
 * the registry is already the single index.
 */

import * as React from "react"
import { getCapabilityRegistry } from "./registry"
import { connectWebMCP } from "./webmcp"

export function AgentUIProvider({
  children,
  enabled = true,
}: {
  children?: React.ReactNode
  enabled?: boolean
}): React.ReactNode {
  const registry = getCapabilityRegistry()

  React.useEffect(() => {
    if (!enabled) return
    return connectWebMCP(registry)
  }, [enabled, registry])

  return children
}

/**
 * Agent UI — capability kernel.
 *
 * A capability is one mounted semantic UI surface. It knows nothing about
 * WebMCP, shadcn, the DOM, the CLI or codemods. It only knows how to report
 * its own semantic state and how to perform its own semantic actions.
 */

/** Semantic state and action result of a capability, always JSON-serialisable. */
export type CapabilityState = Record<string, unknown>

export interface Capability<
  State extends CapabilityState = CapabilityState,
  Actions extends Record<string, unknown> = Record<string, unknown>,
> {
  id: string
  kind: string
  label?: string

  /**
   * Names of the actions this capability supports. Discovery cannot be
   * reconstructed from anywhere else, so the capability declares it.
   */
  actions: readonly (keyof Actions & string)[]

  read(): State

  invoke<Action extends keyof Actions & string>(
    action: Action,
    input: Actions[Action],
  ): Promise<CapabilityResult<State>>
}

/**
 * Result of one semantic action.
 *
 * `state` is read from the component *after* the application has committed the
 * transition, so it is the canonical post-transition state — never a
 * manufactured echo of the request.
 */
export interface CapabilityResult<State extends CapabilityState = CapabilityState> {
  state: State
  /** Optional action-specific return value, e.g. how many rows matched. */
  detail?: unknown
}

/** Machine-readable reasons a semantic dispatch was rejected. */
export type CapabilityErrorCode =
  | "unknown_target"
  | "unsupported_action"
  | "invalid_input"
  | "rejected"

/**
 * Rejection of an agent request. The message is written for an agent to
 * self-correct from and must never carry stack traces, provider names or
 * other internals.
 */
export class CapabilityError extends Error {
  readonly code: CapabilityErrorCode

  constructor(code: CapabilityErrorCode, message: string) {
    super(message)
    this.name = "CapabilityError"
    this.code = code
  }
}

/** Discovery descriptor produced by the registry, never by a component. */
export interface CapabilityDescriptor {
  id: string
  kind: string
  label?: string
  actions: readonly string[]
}

export function describe(capability: Capability): CapabilityDescriptor {
  return {
    id: capability.id,
    kind: capability.kind,
    label: capability.label,
    actions: capability.actions,
  }
}

/**
 * Agent UI — capability registry.
 *
 * Exactly one live registry per document runtime. Registration defines
 * availability; unregistration defines disappearance. There is no
 * reconciliation loop, no DOM scan and no shadow inventory.
 */

import {
  CapabilityError,
  describe,
  type Capability,
  type CapabilityDescriptor,
  type CapabilityResult,
  type CapabilityState,
} from "./capability"

export interface CapabilityRegistry {
  register(capability: Capability): () => void
  get(id: string): Capability | undefined
  list(): Capability[]
  listByKind(kind: string): Capability[]
  listKinds(): string[]
  /** Stable snapshot of every live capability, replaced only when the set changes. */
  describeAll(): CapabilityDescriptor[]
  /** Canonical semantic state of one capability. */
  read(id: string): CapabilityState
  invoke(id: string, action: string, input: unknown): Promise<CapabilityResult>
  /** Notified whenever the set of live capabilities changes. */
  subscribe(listener: () => void): () => void
  /** Document-local identity for a capability that did not supply one. */
  createId(kind: string, seed: string): string
}

function createRegistry(): CapabilityRegistry {
  const capabilities = new Map<string, Capability>()
  const listeners = new Set<() => void>()
  // Snapshot for `useSyncExternalStore`. Held here because the registry is the
  // only thing that knows when the set of capabilities actually changed.
  let snapshot: CapabilityDescriptor[] | undefined

  const notify = () => {
    snapshot = undefined
    for (const listener of [...listeners]) listener()
  }

  const requireCapability = (id: string): Capability => {
    const capability = capabilities.get(id)
    if (!capability) {
      const known = [...capabilities.keys()]
      throw new CapabilityError(
        "unknown_target",
        known.length
          ? `No UI element with id "${id}" is on the page. Available ids: ${known.join(", ")}.`
          : `No UI element with id "${id}" is on the page. There are no agent-operable elements right now.`,
      )
    }
    return capability
  }

  return {
    register(capability) {
      const existing = capabilities.get(capability.id)
      if (existing && existing !== capability) {
        throw new Error(
          `Agent UI: duplicate capability id "${capability.id}". ` +
            `Every mounted capability must have exactly one identity — give one of them a distinct \`agent.id\`.`,
        )
      }
      capabilities.set(capability.id, capability)
      notify()
      return () => {
        if (capabilities.get(capability.id) === capability) {
          capabilities.delete(capability.id)
          notify()
        }
      }
    },

    get(id) {
      return capabilities.get(id)
    },

    list() {
      return [...capabilities.values()]
    },

    listByKind(kind) {
      return [...capabilities.values()].filter((c) => c.kind === kind)
    },

    listKinds() {
      return [...new Set([...capabilities.values()].map((c) => c.kind))].sort()
    },

    describeAll() {
      snapshot ??= [...capabilities.values()].map(describe)
      return snapshot
    },

    read(id) {
      return requireCapability(id).read()
    },

    async invoke(id, action, input) {
      const capability = requireCapability(id)
      if (!capability.actions.includes(action)) {
        throw new CapabilityError(
          "unsupported_action",
          `"${id}" is a ${capability.kind} and does not support "${action}". Supported actions: ${capability.actions.join(", ")}.`,
        )
      }
      return capability.invoke(action, input as never)
    },

    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },

    createId(kind, seed) {
      return `${kind}_${seed.replace(/[^a-zA-Z0-9_-]/g, "")}`
    },
  }
}

const REGISTRY_KEY = Symbol.for("agent-ui.capability-registry")

type RegistryHost = { [REGISTRY_KEY]?: CapabilityRegistry }

/**
 * The single live registry for this document runtime. Keyed off a global
 * symbol so module duplication (HMR, multiple bundles) still resolves to one
 * canonical index.
 */
export function getCapabilityRegistry(): CapabilityRegistry {
  const host = globalThis as RegistryHost
  const existing = host[REGISTRY_KEY]
  if (existing) return existing
  const registry = createRegistry()
  host[REGISTRY_KEY] = registry
  return registry
}

/**
 * Agent UI — protocol-independent tool definitions.
 *
 * This file is deliberately separate from `webmcp.ts`: it defines the agent
 * tool surface as plain data plus executors that dispatch exclusively through
 * the capability registry. It never references `document.modelContext`, so the
 * gallery playground can execute exactly the same definitions against the same
 * registry without a WebMCP-capable browser. `webmcp.ts` is the thin protocol
 * adapter that registers these tools with the browser; everything semantic
 * lives here.
 */

import { CapabilityError, type Capability } from "./capability"
import type { CapabilityRegistry } from "./registry"
import { expectString } from "./validate"

export interface AgentTool {
  name: string
  description: string
  inputSchema: {
    type: "object"
    properties: Record<string, unknown>
    required?: string[]
    additionalProperties: false
  }
  annotations?: { readOnlyHint?: boolean; untrustedContentHint?: boolean }
  execute(input: Record<string, unknown>): Promise<string>
}

const TARGET_PROPERTY = {
  type: "string",
  description: "The id of the UI element to act on, as returned by ui_list.",
}

interface KindToolDef {
  kind: string
  name: string
  action: string
  description: string
  /** Action-specific JSON Schema properties; `target` is added uniformly. */
  inputSchema: Record<string, unknown>
}

/**
 * Declarative mapping from capability kinds to WebMCP tools. Every tool maps
 * 1:1 onto a capability action name. `target` is always required and added by
 * `buildInputSchema`; `ui_list` is how the agent learns valid ids.
 */
const KIND_TOOLS: readonly KindToolDef[] = [
  {
    kind: "tabs",
    name: "tabs_select",
    action: "select",
    description: "Switch the active tab of a tabs element to the given value.",
    inputSchema: {
      value: {
        type: "string",
        description:
          "The tab value to activate. Call ui_read on the target to see available values.",
      },
    },
  },
  {
    kind: "select",
    name: "select_choose",
    action: "choose",
    description: "Choose a value on a select or combobox element.",
    inputSchema: {
      value: {
        type: "string",
        description:
          "The value to choose. Call ui_read on the target to see available values.",
      },
    },
  },
  {
    kind: "select",
    name: "select_clear",
    action: "clear",
    description: "Clear the selection on a select or combobox element.",
    inputSchema: {},
  },
  {
    kind: "checkbox",
    name: "checkbox_set",
    action: "set",
    description: "Set the checked state of a checkbox or switch.",
    inputSchema: {
      checked: {
        type: "boolean",
        description: "Whether the checkbox should be checked.",
      },
    },
  },
  {
    kind: "dialog",
    name: "dialog_open",
    action: "open",
    description: "Open a dialog element.",
    inputSchema: {},
  },
  {
    kind: "dialog",
    name: "dialog_close",
    action: "close",
    description: "Close a dialog element.",
    inputSchema: {},
  },
  {
    kind: "input",
    name: "input_set_value",
    action: "set_value",
    description: "Set the value of a text input or textarea.",
    inputSchema: {
      value: {
        type: "string",
        description: "The new value for the input.",
      },
    },
  },
  {
    kind: "input",
    name: "input_clear",
    action: "clear",
    description: "Clear the value of a text input or textarea.",
    inputSchema: {},
  },
  {
    kind: "data-table",
    name: "table_filter",
    action: "filter",
    description: "Apply a column filter to a data table.",
    inputSchema: {
      column: {
        type: "string",
        description:
          "The column id to filter. Call ui_read on the target to see column ids.",
      },
      value: {
        type: "string",
        description:
          "The filter value to apply. Pass an empty string to clear the filter.",
      },
    },
  },
  {
    kind: "data-table",
    name: "table_sort",
    action: "sort",
    description: "Sort a data table by a column in the given direction.",
    inputSchema: {
      column: {
        type: "string",
        description:
          "The column id to sort by. Call ui_read on the target to see column ids.",
      },
      direction: {
        type: "string",
        enum: ["asc", "desc"],
        description: 'Sort direction: "asc" or "desc".',
      },
    },
  },
  {
    kind: "data-table",
    name: "table_select_rows",
    action: "select_rows",
    description: "Select rows in a data table by id.",
    inputSchema: {
      rowIds: {
        type: "array",
        items: { type: "string" },
        description:
          "The row ids to select. Call ui_read on the target to see row ids.",
      },
    },
  },
  {
    kind: "data-table",
    name: "table_set_page",
    action: "set_page",
    description: "Navigate a paginated data table to a page number.",
    inputSchema: {
      page: {
        type: "integer",
        minimum: 1,
        description: "The 1-based page index to navigate to.",
      },
    },
  },
  {
    kind: "data-table",
    name: "table_set_column_visibility",
    action: "set_column_visibility",
    description: "Show or hide a column in a data table.",
    inputSchema: {
      column: {
        type: "string",
        description:
          "The column id to show or hide. Call ui_read on the target to see column ids.",
      },
      visible: {
        type: "boolean",
        description: "True to show the column, false to hide it.",
      },
    },
  },
]

/**
 * Agent context budget (Chrome WebMCP guidance): a tool output above roughly
 * 1.5K characters makes agents trip their own guardrails.
 */
const MAX_OUTPUT = 1500

/**
 * Serialise a tool result for the agent. WebMCP requires string output. When
 * the payload exceeds the budget the envelope stays valid JSON and says so,
 * rather than handing the agent a truncated fragment it cannot parse.
 */
function serialise(value: unknown): string {
  const json = JSON.stringify(value)
  if (json.length <= MAX_OUTPUT) return json
  return JSON.stringify({
    ok: true,
    truncated: true,
    reason: `The result is ${json.length} characters, above the ${MAX_OUTPUT} character tool output budget. Narrow the request, for example by filtering or paging.`,
  })
}

function withoutTarget(input: Record<string, unknown>): Record<string, unknown> {
  const rest: Record<string, unknown> = { ...input }
  delete rest.target
  return rest
}

/**
 * `AgentAction` validates its own id, so no sanitising or truncation is needed
 * here - a name that could collide would be a developer error the component
 * already refuses.
 */
function actionToolName(id: string): string {
  return `action_${id}`
}

function buildInputSchema(
  properties: Record<string, unknown>,
): AgentTool["inputSchema"] {
  return {
    type: "object",
    properties: { target: TARGET_PROPERTY, ...properties },
    required: ["target", ...Object.keys(properties)],
    additionalProperties: false,
  }
}

function makeExecutor(
  toolName: string,
  run: (input: Record<string, unknown>) => Promise<string>,
): AgentTool["execute"] {
  return async (input: Record<string, unknown>): Promise<string> => {
    try {
      return await run(input)
    } catch (error) {
      // CapabilityError messages are written for agent self-correction.
      if (error instanceof CapabilityError) throw error
      // Any other thrown value is a bug in the page. Log the full error for
      // debugging; surface only a neutral message that names the tool.
      console.error("[agent-ui]", error)
      throw new Error(`The "${toolName}" tool could not complete.`)
    }
  }
}

function createListTool(registry: CapabilityRegistry): AgentTool {
  return {
    name: "ui_list",
    description:
      "List the agent-operable UI elements currently on the page, with their id, kind, label and available actions. Call this first to discover valid target ids.",
    inputSchema: {
      type: "object",
      properties: {},
      required: [],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true },
    execute: makeExecutor("ui_list", async () => {
      const capabilities = registry.describeAll()
      return serialise({ ok: true, action: "list", state: { capabilities } })
    }),
  }
}

function createReadTool(registry: CapabilityRegistry): AgentTool {
  return {
    name: "ui_read",
    description:
      "Read the current semantic state of one UI element by id. Use ui_list first to discover valid ids.",
    inputSchema: {
      type: "object",
      properties: { target: TARGET_PROPERTY },
      required: ["target"],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true },
    execute: makeExecutor("ui_read", async (input) => {
      const target = expectString(input, "target")
      // The registry owns target resolution and its rejection message.
      const state = registry.read(target)
      return serialise({ ok: true, target, action: "read", state })
    }),
  }
}

function createKindTool(
  registry: CapabilityRegistry,
  def: KindToolDef,
): AgentTool {
  return {
    name: def.name,
    description: def.description,
    inputSchema: buildInputSchema(def.inputSchema),
    // Every kind tool mutates component state; reads go through ui_read.
    execute: makeExecutor(def.name, async (input) => {
      const target = expectString(input, "target")
      const actionInput = withoutTarget(input)
      const result = await registry.invoke(target, def.action, actionInput)
      return serialise({
        ok: true,
        target,
        action: def.action,
        state: result.state,
        detail: result.detail,
      })
    }),
  }
}

/**
 * Shape an `AgentAction` capability reports through `read()`. `Capability.read`
 * is typed as an open record, so the contract is narrowed here rather than cast.
 */
interface ActionCapabilityState {
  description: string
  inputSchema?: Record<string, unknown>
  requiresConfirmation: boolean
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function readActionState(capability: Capability): ActionCapabilityState | undefined {
  const state = capability.read()
  if (typeof state.description !== "string" || state.description.length === 0) {
    return undefined
  }
  return {
    description: state.description,
    inputSchema: isRecord(state.inputSchema) ? state.inputSchema : undefined,
    requiresConfirmation: state.requiresConfirmation === true,
  }
}

function createActionTool(
  registry: CapabilityRegistry,
  capability: Capability,
  state: ActionCapabilityState,
): AgentTool {
  const name = actionToolName(capability.id)
  const userInputSchema = state.inputSchema ?? {}

  // A business action tool is bound to exactly one capability, so it carries no
  // `target`: the tool name already identifies what it operates on.
  const properties: Record<string, unknown> = { ...userInputSchema }
  const required = Object.keys(userInputSchema)

  if (state.requiresConfirmation) {
    properties.confirmed = {
      type: "boolean",
      description: "Set to true to confirm this consequential action.",
    }
    required.push("confirmed")
  }

  return {
    name,
    description: state.description,
    inputSchema: {
      type: "object",
      properties,
      required,
      additionalProperties: false,
    },
    // Business actions are never read-only.
    execute: makeExecutor(name, async (input) => {
      const result = await registry.invoke(capability.id, "run", input)
      return serialise({
        ok: true,
        target: capability.id,
        action: "run",
        state: result.state,
        detail: result.detail,
      })
    }),
  }
}

/** Every tool that the currently mounted capabilities justify. */
export function createAgentTools(registry: CapabilityRegistry): AgentTool[] {
  const tools: AgentTool[] = [createListTool(registry), createReadTool(registry)]

  const mountedKinds = new Set(registry.listKinds())
  for (const def of KIND_TOOLS) {
    if (mountedKinds.has(def.kind)) {
      tools.push(createKindTool(registry, def))
    }
  }

  for (const capability of registry.listByKind("action")) {
    const state = readActionState(capability)
    if (!state) {
      // Only AgentAction produces this kind, and it validates its own props, so
      // this means something else registered kind "action" with a state that is
      // not an action. Report it and expose no tool for it rather than
      // advertising an action with no description.
      console.error(
        "[agent-ui]",
        `Capability "${capability.id}" registered as kind "action" without a description.`,
      )
      continue
    }
    tools.push(createActionTool(registry, capability, state))
  }

  return tools
}

"use client"

/**
 * Agent UI - React view of the live capability registry.
 *
 * The registry owns the snapshot, so this hook is a direct
 * `useSyncExternalStore` over it. Caching the snapshot here instead would go
 * stale whenever the registry changed while no component was subscribed.
 */

import * as React from "react"

import type { CapabilityDescriptor } from "./capability"
import { getCapabilityRegistry } from "./registry"

/** No capabilities exist during SSR: nothing has mounted yet. */
const SERVER_SNAPSHOT: CapabilityDescriptor[] = []

export function useCapabilities(): CapabilityDescriptor[] {
  const registry = getCapabilityRegistry()

  return React.useSyncExternalStore(
    registry.subscribe,
    registry.describeAll,
    () => SERVER_SNAPSHOT,
  )
}

"use client"

/**
 * Agent UI - React binding.
 *
 * Translates component-native behaviour into semantic capability actions.
 * React remains the canonical state owner: nothing here stores a copy of
 * component state, and every action result is read back from the component
 * after the application has committed the transition.
 */

import * as React from "react"

import type { Capability, CapabilityResult, CapabilityState } from "./capability"
import { CapabilityError } from "./capability"
import { getCapabilityRegistry } from "./registry"

/** Value of the `agent` prop that every agent-operable component accepts. */
export type AgentConfig = {
  /** Stable identity. Omit to receive a document-local generated identity. */
  id?: string
  /** Human-meaningful name the agent sees in discovery. */
  label?: string
}

export type AgentProp = AgentConfig | boolean

export type ActionMap<Actions extends Record<string, unknown>> = {
  [Action in keyof Actions & string]: (
    input: Actions[Action],
  ) => unknown | Promise<unknown>
}

export interface UseCapabilityOptions<
  State extends CapabilityState,
  Actions extends Record<string, unknown>,
> {
  agent?: AgentProp
  kind: string
  /** Label used when the `agent` prop does not carry one. */
  defaultLabel?: string
  read: () => State
  actions: ActionMap<Actions>
}

export interface CapabilityHandle {
  /** Resolved identity, or undefined when the component opted out. */
  id: string | undefined
  registered: boolean
}

/**
 * Resolves once React has had the chance to run the work an action scheduled.
 *
 * React's scheduler performs its work on a host task, and which host task
 * differs by environment: a `MessageChannel` message in browsers, a
 * `setImmediate` callback under Node. Two turns of the task queue land after
 * either. This is only the floor for the case where nothing commits at all,
 * because a real commit resolves the waiter the instant it happens, so the
 * bound costs the accepted path nothing.
 *
 * An update the application deliberately defers with `startTransition` can
 * still commit later than this. Reporting the state as it actually stands at
 * that moment is the honest answer, not something to compensate for.
 */
function afterReactFlush(): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(() => setTimeout(resolve, 0), 0)
  })
}

function resolveConfig(agent: AgentProp | undefined): AgentConfig | undefined {
  if (agent === false) return undefined
  if (agent === true || agent === undefined) return {}
  return agent
}

export function useCapability<
  State extends CapabilityState,
  Actions extends Record<string, unknown>,
>(options: UseCapabilityOptions<State, Actions>): CapabilityHandle {
  const { agent, kind, defaultLabel, read, actions } = options

  const config = resolveConfig(agent)
  const registry = getCapabilityRegistry()
  const generatedId = registry.createId(kind, React.useId())
  const id = config ? (config.id ?? generatedId) : undefined
  const label = config?.label ?? defaultLabel

  const actionKey = Object.keys(actions).sort().join(" ")
  const actionNames = React.useMemo(
    () => actionKey.split(" ").filter(Boolean) as (keyof Actions & string)[],
    [actionKey],
  )

  const readRef = React.useRef(read)
  const actionsRef = React.useRef(actions)
  const commitWaiters = React.useRef(new Set<() => void>())

  // Runs on every commit, before passive effects. Afterwards the refs hold the
  // committed render's closures, so a capability read always sees canonical
  // state rather than the state captured at registration time.
  React.useLayoutEffect(() => {
    readRef.current = read
    actionsRef.current = actions
    if (commitWaiters.current.size === 0) return
    const pending = [...commitWaiters.current]
    commitWaiters.current.clear()
    for (const resolve of pending) resolve()
  })

  const waitForCommit = React.useCallback(() => {
    return new Promise<void>((resolve) => {
      let settled = false
      const finish = () => {
        if (settled) return
        settled = true
        commitWaiters.current.delete(finish)
        resolve()
      }
      commitWaiters.current.add(finish)
      // No commit means the application did not accept the transition. Resolve
      // once React's scheduled work for this tick has run, so the result
      // reports the real, unchanged state instead of a manufactured success.
      void afterReactFlush().then(finish)
    })
  }, [])

  const [registered, setRegistered] = React.useState(false)

  React.useEffect(() => {
    if (!id) return

    const capability: Capability<State, Actions> = {
      id,
      kind,
      label,
      actions: actionNames,
      read: () => readRef.current(),
      async invoke(action, input): Promise<CapabilityResult<State>> {
        const handler = actionsRef.current[action]
        if (!handler) {
          throw new CapabilityError(
            "unsupported_action",
            `"${id}" does not support "${action}". Supported actions: ${actionNames.join(", ")}.`,
          )
        }
        // 1. The component performs the transition, the application decides.
        const detail = await handler(input)
        // 2. React commits whatever the application decided.
        await waitForCommit()
        // 3. The result is canonical state, read after the commit.
        return { state: readRef.current(), detail }
      },
    }

    const unregister = registry.register(capability as Capability)
    setRegistered(true)
    return () => {
      unregister()
      setRegistered(false)
    }
  }, [registry, id, kind, label, actionNames, waitForCommit])

  return { id, registered }
}

"use client"

import * as React from "react"

export function useControllableState<T>(options: {
  prop: T | undefined
  defaultProp: T
  onChange?: (value: T) => void
}): [T, (next: T) => void] {
  const { prop, defaultProp, onChange } = options

  const [internal, setInternal] = React.useState<T>(defaultProp)
  const value = prop !== undefined ? (prop as T) : internal

  const latest = React.useRef({ isControlled: prop !== undefined, onChange })
  React.useLayoutEffect(() => {
    latest.current = { isControlled: prop !== undefined, onChange }
  })

  const setValue = React.useCallback(
    (next: T) => {
      if (!latest.current.isControlled) {
        setInternal(next)
      }
      latest.current.onChange?.(next)
    },
    [],
  )

  return [value, setValue]
}

/**
 * Agent UI — input validation.
 *
 * Agent input is untrusted. These helpers reject invalid requests with
 * messages an agent can self-correct from. They never coerce, never guess and
 * never compensate for a missing semantic.
 */

import { CapabilityError } from "./capability"

function reject(message: string): never {
  throw new CapabilityError("invalid_input", message)
}

export function expectObject(input: unknown): Record<string, unknown> {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    reject("Arguments must be an object.")
  }
  return input as Record<string, unknown>
}

export function expectString(input: unknown, field: string): string {
  const value = expectObject(input)[field]
  if (typeof value !== "string") reject(`"${field}" must be a string.`)
  return value
}

export function expectOptionalString(input: unknown, field: string): string | undefined {
  const value = expectObject(input)[field]
  if (value === undefined || value === null) return undefined
  if (typeof value !== "string") reject(`"${field}" must be a string.`)
  return value
}

export function expectBoolean(input: unknown, field: string): boolean {
  const value = expectObject(input)[field]
  if (typeof value !== "boolean") reject(`"${field}" must be true or false.`)
  return value
}

export function expectInteger(input: unknown, field: string, min: number): number {
  const value = expectObject(input)[field]
  if (typeof value !== "number" || !Number.isInteger(value)) {
    reject(`"${field}" must be a whole number.`)
  }
  if (value < min) reject(`"${field}" must be ${min} or greater.`)
  return value
}

export function expectStringArray(input: unknown, field: string): string[] {
  const value = expectObject(input)[field]
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
    reject(`"${field}" must be an array of strings.`)
  }
  return value as string[]
}

export function expectOneOf<T extends string>(
  value: string,
  allowed: readonly T[],
  field: string,
): T {
  if (!allowed.includes(value as T)) {
    reject(`"${field}" must be one of: ${allowed.join(", ")}. Received "${value}".`)
  }
  return value as T
}

/** Rejects an action the current component state does not permit. */
export function rejectState(message: string): never {
  throw new CapabilityError("rejected", message)
}

/**
 * Agent UI - WebMCP protocol adapter.
 *
 * The only layer that touches `document.modelContext`. It translates the
 * capability registry into WebMCP tools and dispatches agent calls back
 * through the registry, never through the DOM. Tool count scales with
 * capability kinds, not component instances.
 */

import type { CapabilityRegistry } from "./registry"
import { createAgentTools, type AgentTool } from "./tools"

export function isWebMCPSupported(): boolean {
  return getModelContext() != null
}

function getModelContext(): WebMCP.ModelContext | undefined {
  if (typeof document === "undefined") return undefined
  return document.modelContext
}

/**
 * `webmcp-types@0.1.5` does not yet declare `executeTool`, which the WebMCP
 * specification puts on `ModelContext`. Narrowing it here keeps the gap in the
 * one file allowed to know about the protocol.
 *
 * The specification types the second argument as an `object` and serialises it
 * itself, but Chrome's shipping implementation takes the already-serialised
 * JSON string and rejects anything else with "Failed to parse input arguments".
 * This declares what the browser actually accepts.
 * https://developer.chrome.com/docs/ai/webmcp/imperative-api
 */
interface ModelContextWithExecute extends WebMCP.ModelContext {
  executeTool(
    tool: WebMCP.RegisteredTool,
    inputArguments?: string,
  ): Promise<string>
}

/**
 * Runs a registered tool the way an agent would: through the browser's own
 * WebMCP dispatch rather than by calling the tool definition directly.
 *
 * This exists so nothing outside the adapter has to reach for
 * `document.modelContext` (spec invariant 6). It resolves to the tool's string
 * result, and rejects when WebMCP is unavailable or the tool is not registered
 * yet.
 */
export async function executeViaWebMCP(
  name: string,
  input: Record<string, unknown>,
): Promise<string> {
  const modelContext = getModelContext() as ModelContextWithExecute | undefined
  if (!modelContext) {
    throw new Error("WebMCP is not available in this browser.")
  }
  const registered = await modelContext.getTools()
  const tool = registered.find((candidate) => candidate.name === name)
  if (!tool) {
    throw new Error(`The "${name}" tool is not registered with the browser yet.`)
  }
  return modelContext.executeTool(tool, JSON.stringify(input))
}

function toWebMCPTool(tool: AgentTool): WebMCP.ModelContextTool {
  return {
    name: tool.name,
    description: tool.description,
    inputSchema: tool.inputSchema,
    annotations: tool.annotations,
    execute: (inputObject) => tool.execute(inputObject),
  }
}

export function connectWebMCP(registry: CapabilityRegistry): () => void {
  const modelContext = getModelContext()
  if (!modelContext) {
    // Progressive enhancement (spec section 11): without WebMCP the app stays
    // ordinary React UI. Register nothing, tear down nothing.
    return () => {}
  }

  const controllers = new Map<string, AbortController>()
  let disposed = false
  let running = false
  let dirty = false

  /**
   * Brings the registered tool set in line with the registry exactly once.
   * Registration is asynchronous, so `schedule` guarantees runs never
   * interleave rather than reconciling a moving target.
   */
  const reconcile = async () => {
    const desired = createAgentTools(registry)
    const desiredNames = new Set(desired.map((tool) => tool.name))

    for (const [name, controller] of [...controllers]) {
      if (!desiredNames.has(name)) {
        controller.abort()
        controllers.delete(name)
      }
    }

    for (const tool of desired) {
      // A kept registration is always current: its execute closure reads the
      // registry live, so there is nothing to refresh and no churn to cause.
      if (controllers.has(tool.name)) continue

      const controller = new AbortController()
      try {
        await modelContext.registerTool(toWebMCPTool(tool), {
          signal: controller.signal,
        })
      } catch (error) {
        // Progressive enhancement again: a failed registration must never
        // break human interaction. This is the one place a catch is correct.
        console.warn(
          "[agent-ui]",
          `Failed to register the WebMCP tool "${tool.name}":`,
          error,
        )
        continue
      }

      if (disposed) {
        controller.abort()
        continue
      }
      controllers.set(tool.name, controller)
    }
  }

  const schedule = () => {
    if (running) {
      dirty = true
      return
    }
    running = true
    void (async () => {
      do {
        dirty = false
        await reconcile()
      } while (dirty && !disposed)
      running = false
    })()
  }

  const unsubscribe = registry.subscribe(schedule)
  schedule()

  return () => {
    disposed = true
    unsubscribe()
    for (const controller of controllers.values()) {
      controller.abort()
    }
    controllers.clear()
  }
}
